import numpy as np
import pandas as pd

def r_colnames(x, do_NULL=True, prefix="col"):
    """
    Reproduces the R function `colnames`.
    """
    # R's is.data.frame(x)
    is_df = isinstance(x, pd.DataFrame)

    if is_df and do_NULL:
        # R: names(x) for data frames returns the column names
        return list(x.columns)

    # R: dimnames(x)[[2L]]
    # For pandas DataFrames, x.columns is the equivalent of dimnames[[2]]
    # For numpy arrays, we check if it has a .columns attribute or similar
    cols = None
    if is_df:
        cols = list(x.columns)
    elif hasattr(x, 'columns'):
        cols = list(x.columns)
    elif hasattr(x, 'ndim') and x.ndim >= 2:
        # In R, matrices often have NULL colnames unless set.
        # NumPy arrays generally don't have colnames.
        cols = None

    if cols is not None:
        return cols

    if do_NULL:
        return None
    else:
        # R: NCOL(x)
        # NCOL returns the number of columns.
        # For numpy arrays or DataFrames.
        nc = 0
        if is_df:
            nc = x.shape[1]
        elif hasattr(x, 'shape'):
            if len(x.shape) >= 2:
                nc = x.shape[1]
            elif len(x.shape) == 1:
                nc = 1

        if nc > 0:
            # R: paste0(prefix, seq_len(nc))
            # seq_len(nc) is 1, 2, ..., nc
            return [f"{prefix}{i}" for i in range(1, nc + 1)]
        else:
            # R: character()
            return []
